package main

import "fmt"

func main() {
	var n int
	fmt.Scan(&n)

	step := 0
	check := false

	if n == 1 {
		fmt.Println(1)
		return
	} else if n == 2 {
		fmt.Println(1)
		return
	} else if n == 5 {
		fmt.Println(3)
		return
	}

	for n != 0 && n != 5 {
		if !check {
			if n != 0 {
				n--
				step++
				check = true
			}
		}
		if check {
			if n != 0 {
				n -= 2
				step++
				check = false
			}
		}
		if n == 1 {
			step++
			break
		} else if n == 2 {
			step++
			break
		} else if n == 5 {
			step += 3
			break
		}
	}

	fmt.Println(step)
}

